mapper.select:
SELECT id
FROM notification_delivery
WHERE channel = #{channel}
  AND status IN ('PENDING', 'FAILED_RETRYABLE', 'PROCESSING')
  AND next_attempt_at <= #{now}
  AND (lease_until IS NULL OR lease_until < #{now})
ORDER BY next_attempt_at
LIMIT #{batchSize}

mapper.update:
UPDATE notification_delivery
SET status = 'PROCESSING',
    claim_token = #{claimToken},
    lease_until = #{leaseUntil},
    attempt_count = attempt_count + 1,
    updated_at = #{now}
WHERE id = #{id}
  AND status IN ('PENDING', 'FAILED_RETRYABLE', 'PROCESSING')
  AND next_attempt_at <= #{now}
  AND (lease_until IS NULL OR lease_until < #{now})

UPDATE notification_delivery
SET unknown_outcome_count = 1,
    send_attempted_at = NULL,
    updated_at = #{now}
WHERE id = #{id}
  AND claim_token = #{claimToken}
  AND send_attempted_at IS NOT NULL
  AND unknown_outcome_count = 0

UPDATE notification_delivery
SET send_attempted_at = #{now}, updated_at = #{now}
WHERE id = #{id}
  AND claim_token = #{claimToken}
  AND status = 'PROCESSING'
  AND lease_until > #{now}

UPDATE notification_delivery
SET status = 'SENT', sent_at = #{now}, provider_message_id = #{providerMessageId},
    lease_until = NULL, updated_at = #{now}
WHERE id = #{id} AND claim_token = #{claimToken}

UPDATE notification_delivery
SET status = 'DRY_RUN', sent_at = #{now}, provider_message_id = #{providerMessageId},
    lease_until = NULL, updated_at = #{now}
WHERE id = #{id} AND claim_token = #{claimToken}

UPDATE notification_delivery
SET status = #{status},
    failure_category = #{failureCategory},
    lease_until = NULL,
    updated_at = #{now}
WHERE id = #{id} AND claim_token = #{claimToken}

mapper.select:
SELECT DISTINCT tenant_id AS tenantId, recipient_user_id AS recipientUserId
FROM notification_delivery
WHERE channel = 'DAILY_DIGEST'
  AND status = 'PENDING'
  AND digest_date <= #{digestDate}
  AND tenant_id = #{tenantId}

mapper.update:
UPDATE notification_delivery
SET digest_email_id = #{digestEmailId},
    digest_date = #{digestDate},
    status = 'PROCESSING'
WHERE channel = 'DAILY_DIGEST'
  AND status = 'PENDING'
  AND digest_date <= #{digestDate}
  AND tenant_id = #{tenantId}
  AND recipient_user_id = #{recipientUserId}

UPDATE notification_delivery
SET status = 'SKIPPED_PREFERENCE',
    failure_category = 'PERMANENT_PREFERENCE'
WHERE channel = 'DAILY_DIGEST'
  AND status = 'PENDING'
  AND digest_date <= #{digestDate}
  AND tenant_id = #{tenantId}
  AND recipient_user_id = #{recipientUserId}

UPDATE notification_delivery
SET digest_date = #{toDate}
WHERE channel = 'DAILY_DIGEST'
  AND status = 'PENDING'
  AND digest_date <= #{fromDate}
  AND tenant_id = #{tenantId}
  AND recipient_user_id = #{recipientUserId}
  AND digest_email_id IS NULL

UPDATE notification_delivery
SET status = #{status}, lease_until = NULL, sent_at = CASE WHEN #{status} IN ('SENT', 'DRY_RUN') THEN #{now} ELSE sent_at END,
    updated_at = #{now}
WHERE digest_email_id = #{digestEmailId}
